/**
 * The application's contracts (ADR-015): the shape of what forge renders from the
 * configuration into ./config.ts, and what the project passes to the router factory.
 * Generated by forge; change the configuration and regenerate instead of editing.
 */
import type { Component, Ref } from 'vue'
import type { RouteRecordRaw, RouterHistory } from 'vue-router'

/** A menu item as the configuration declares it: at most one of to, action, children. */
export interface MenuItemConfig {
  id: string
  label: string
  icon?: string
  /** A route name. */
  to?: string
  /** An action id the project passes to the router factory (`actions`). */
  action?: string
  /** A key whose value the project supplies at runtime (provideMenuBadges). */
  badge?: string
  /** One level of sub-items. */
  children?: MenuItemConfig[]
}

export interface MenuSectionConfig {
  /** The section's eyebrow label. */
  label?: string
  items: MenuItemConfig[]
}

export type MenuName = 'primary' | 'account' | 'footer'

export interface LayoutConfig {
  shell: string
  /** The route a placeholder item opens, with `{ item: <id> }`; none renders them disabled. */
  placeholder: string | null
  menus: Record<MenuName, MenuSectionConfig[]>
}

export type RoutingKey = 'landing' | 'sign_in' | 'not_found' | 'auth_stuck' | 'forbidden'

export interface ApplicationConfig {
  title: string
  /** Whether the app signs users in (include_auth). */
  auth: boolean
  /** The route name of each destination the guards use; absent when the app has none. */
  routing: Partial<Record<RoutingKey, string>>
  /** The destinations whose page forge renders. */
  builtin: RoutingKey[]
  layouts: Record<string, LayoutConfig>
  /** The sample pages (extras) the router factory registers under the first layout. */
  extras: string[]
}

/** What the guards, the API client and the shell need to know about the signed-in user. */
export interface AuthContract {
  readonly isAuthenticated: Readonly<Ref<boolean>>
  readonly isLoading: Readonly<Ref<boolean>>
  readonly user: Readonly<Ref<unknown>>
  hasRole(role: string): boolean
  /** Start signing in; `redirect` is where the user returns afterwards. */
  signIn(redirect?: string): void | Promise<void>
  signOut(): void | Promise<void>
  /** Called once before the app mounts. */
  init?(): Promise<void>
}

export type MenuAction = () => unknown

export interface ApplicationOptions {
  auth: AuthContract
  /** The project's pages, per layout name. */
  routes?: Record<string, RouteRecordRaw[]>
  /** Routes outside every layout, such as a project's own sign-in page. */
  publicRoutes?: RouteRecordRaw[]
  /** A component per layout that wraps the layout's shell and fills its slots. */
  layouts?: Record<string, Component>
  /** The menu actions, by the ids the configuration names. */
  actions?: Record<string, MenuAction>
  /** The layouts mounted in this browser session; every layout by default. */
  activeLayouts?: string[]
  history?: RouterHistory
}
